@tl.constexpr
def _get_sign_bit_mask(num_bits):
    num_bits = _unwrap_if_constexpr(num_bits)
    return 1 << (num_bits - 1)


@libentry()
@triton.jit(do_not_specialize=["N"])
def _copysign_inplace_flat_kernel(X, Y, N, BLOCK: tl.constexpr, EVEN: tl.constexpr):
    pid = tl.program_id(0)
    num_ctas = tl.num_programs(0)
    num_tiles = tl.cdiv(N, BLOCK)
    for tile in tl.range(pid, num_tiles, num_ctas):
        offs = tile * BLOCK + tl.arange(0, BLOCK)
        if EVEN:
            x = tl.load(X + offs)
            y = tl.load(Y + offs)
        else:
            mask = offs < N
            x = tl.load(X + offs, mask=mask)
            y = tl.load(Y + offs, mask=mask)
        abs_val = tl.abs(x)
        num_bits: tl.constexpr = x.dtype.primitive_bitwidth
        uint_dtype = _get_uint_dtype(num_bits)
        sign_bit_mask: tl.constexpr = _get_sign_bit_mask(num_bits)
        other_u = y.to(uint_dtype, bitcast=True)
        res = tl.where((other_u & sign_bit_mask) != 0, -abs_val, abs_val)
        if EVEN:
            tl.store(X + offs, res)
        else:
            tl.store(X + offs, res, mask=mask)


def _copysign_flat_block(numel):
    if numel <= 8192:
        return max(triton.next_power_of_2(numel), 256)
    if numel <= 65536:
        return 8192
    if numel <= 524288:
        return 32768
    return 65536


def _max_flat_offset(t):
    offset = 0
    for size, stride in zip(t.shape, t.stride()):
        if size > 1:
            offset += (size - 1) * stride
    return offset


def _launch_flat(x, y, numel):
    block = _copysign_flat_block(numel)
    grid = (min(triton.cdiv(numel, block), _FLAT_GRID_CAP),)
    even = numel % block == 0
    for attempt in range(3):
        try:
            with torch_device_fn.device(x.device):
                _copysign_inplace_flat_kernel[grid](
                    x,
                    y,
                    numel,
                    BLOCK=block,
                    EVEN=even,
                    num_warps=2,
                )
            return
        except Exception as exc:
            if attempt == 2:
                raise
            logger.warning(
                "copysign_ flat kernel launch failed (attempt %d): %s",
                attempt + 1,
                exc,
            )


